import { afterEach, beforeEach, expect, it, vi } from 'vitest'
import feedXML from './__fixtures__/feed.atom?raw'
import { fetchFeed, login, logout, threadURL } from './agg'
import { settings } from './settings'

const AGG = 'https://agg.example'

beforeEach(() => {
  // The fixture was generated by an amfeed at this base URL.
  settings.feedServer = 'http://localhost:8198'
  settings.token = 'amf_posting'
  logout()
})
afterEach(() => vi.unstubAllGlobals())

interface Call {
  method: string
  url: string
  auth: string | null
  body: string | null
}

function stubFetch(handler: (c: Call) => Response): Call[] {
  const calls: Call[] = []
  vi.stubGlobal(
    'fetch',
    vi.fn(async (url: string, init?: RequestInit) => {
      const headers = new Headers(init?.headers)
      const c = {
        method: init?.method ?? 'GET',
        url,
        auth: headers.get('Authorization'),
        body: (init?.body as string | undefined) ?? null,
      }
      calls.push(c)
      return handler(c)
    }),
  )
  return calls
}

it('logs in by publishing the challenge on the feed server', async () => {
  const calls = stubFetch((c) => {
    if (c.url === 'http://localhost:8198/feed.atom') return new Response(feedXML)
    if (c.url === AGG + '/api/login') return Response.json({ token: 'tok123' })
    if (c.url === 'http://localhost:8198/api/challenges/tok123') return new Response(null, { status: 204 })
    if (c.url === AGG + '/api/login/verify')
      return Response.json({
        token: 'ama_session',
        name: 'localhost_8198',
        timeline_url: AGG + '/timeline/localhost_8198.atom',
      })
    return new Response('not found', { status: 404 })
  })

  await login(AGG + '/', 'inv_x')

  const loginCall = calls.find((c) => c.url === AGG + '/api/login')!
  expect(JSON.parse(loginCall.body!)).toEqual({ author_uri: 'http://localhost:8198/', invite: 'inv_x' })
  const put = calls.find((c) => c.method === 'PUT')!
  expect(put.body).toBe('tok123.https://agg.example') // bound to this aggregator's origin
  expect(put.auth).toBe('Bearer amf_posting')
  // The posting token goes to the feed server only.
  expect(calls.filter((c) => c.url.startsWith(AGG)).every((c) => c.auth === null)).toBe(true)

  expect(settings.aggregator).toBe(AGG)
  expect(settings.aggToken).toBe('ama_session')
  expect(settings.source).toBe('home')
})

it('fetches aggregator feeds with the session token and others through the proxy', async () => {
  settings.aggregator = AGG
  settings.aggToken = 'ama_session'
  const calls = stubFetch(() => new Response(feedXML))

  await fetchFeed(AGG + '/timeline/me.atom')
  await fetchFeed('https://blog.example/feed.atom')
  await fetchFeed('http://localhost:8198/feed.atom')

  expect(calls[0]).toMatchObject({ url: AGG + '/timeline/me.atom', auth: 'Bearer ama_session' })
  expect(calls[1]).toMatchObject({
    url: AGG + '/api/feed?url=' + encodeURIComponent('https://blog.example/feed.atom'),
    auth: 'Bearer ama_session',
  })
  expect(calls[2]).toMatchObject({ url: 'http://localhost:8198/feed.atom', auth: null })
})

it('knows thread feeds only for posts on the aggregator', () => {
  settings.aggregator = AGG
  settings.aggToken = 'ama_session'
  expect(threadURL(AGG + '/posts/12')).toBe(AGG + '/posts/12/thread.atom')
  expect(threadURL('https://elsewhere.example/posts/12')).toBe('')
  expect(threadURL(AGG + '/timeline.atom')).toBe('')
})
